import React, { useState } from "react";
import ComplaintForm from "./components/ComplaintForm";

function App() {
  const [complaints, setComplaints] = useState([]);

  const handleComplaintSubmit = (newComplaint) => {
    console.log("Complaint submitted:", newComplaint);
    setComplaints([...complaints, newComplaint]);

    // Later we can send this to backend using fetch/axios
  };

  return (
    <div>
      <h1>Complaint Portal</h1>
      <ComplaintForm onComplaintSubmit={handleComplaintSubmit} />
      <ul>
        {complaints.map((c, index) => (
          <li key={index}>{c}</li>
        ))}
      </ul>
    </div>
  );
}

export default App;
